// Edit PROFILE to match profile.json (same fields). Runs once for all items.
const PROFILE = {
  candidate: {
    summary: 'EDIT ME: 2-3 plain sentences about you.',
    target_roles: ['data analyst intern', 'AI intern', 'machine learning intern'],
    skills: ['Python', 'SQL', 'Excel'],
    location_preference: 'remote or Australia',
    avoid: ['senior', '10+ years'],
  },
  keywords: ['intern', 'internship', 'graduate', 'junior', 'entry level', 'data analyst', 'machine learning', 'AI'],
  max_to_score: 30,
};
const strip = (t, n = 600) => String(t || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);

const remotive = ($('Fetch Remotive').first().json.jobs || []).map(j => ({
  source: 'remotive', title: j.title, company: j.company_name, url: j.url,
  location: j.candidate_required_location || '', description: strip(j.description),
}));
const arbeitnow = ($input.first().json.data || []).slice(0, 100).map(j => ({
  source: 'arbeitnow', title: j.title, company: j.company_name, url: j.url,
  location: j.location || '', description: strip(j.description),
}));

// Dedupe against what earlier runs already saw (kept in workflow static data; only persists when the workflow is active).
const store = $getWorkflowStaticData('global');
const seen = new Set(store.seen || []);
if (PROFILE.candidate.summary.startsWith('EDIT ME')) throw new Error('Fill in PROFILE.candidate.summary first.');
const kw = new RegExp('\\b(' + PROFILE.keywords.map(k => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|') + ')\\b', 'i');
const batch = new Set();
const fresh = [];
for (const j of [...remotive, ...arbeitnow]) {
  const key = (j.company + '|' + j.title).toLowerCase();
  if (!j.url || seen.has(j.url) || batch.has(key) || !kw.test(j.title + ' ' + j.description)) continue;
  batch.add(key);
  fresh.push(j);
}
const postings = fresh.slice(0, PROFILE.max_to_score).map((j, i) => ({ ...j, id: String(i) }));
store.seen = [...seen, ...postings.map(j => j.url)].slice(-3000);
if (!postings.length) return [];

const prompt = 'You rate job postings for one candidate. Be strict and honest.\n' +
  'Candidate profile (JSON): ' + JSON.stringify(PROFILE.candidate) + '\n' +
  'For each posting give an integer fit score 0-10 and a reason of at most 15 words.\n' +
  'Reply as a JSON array: [{"id": "0", "score": 7, "reason": "..."}]. Use the given ids.\n' +
  'Postings: ' + JSON.stringify(postings.map(({ id, title, company, location, description }) => ({ id, title, company, location, description })));
return [{ json: { postings, body: { contents: [{ parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json', temperature: 0.2 } } } }];

// Join Gemini scores to postings, keep the top N, build the digest text.
const TOP_N = 5, MIN_SCORE = 6;
const postings = $('Normalize and dedupe').first().json.postings;
let rows = [];
try { rows = JSON.parse($input.first().json.candidates[0].content.parts[0].text); } catch (e) { rows = []; }
const byId = Object.fromEntries(postings.map(p => [p.id, p]));
const ranked = (Array.isArray(rows) ? rows : [])
  .filter(r => byId[r.id] && Number.isFinite(Number(r.score)))
  .map(r => ({ ...byId[r.id], score: Math.max(0, Math.min(10, Math.round(Number(r.score)))), reason: String(r.reason || '').slice(0, 160) }))
  .filter(r => r.score >= MIN_SCORE)
  .sort((a, b) => b.score - a.score)
  .slice(0, TOP_N);
if (!ranked.length) return [];
const date = new Date().toISOString().slice(0, 10);
const lines = ['Job digest ' + date + ' - ' + ranked.length + ' match(es)', ''];
ranked.forEach((r, i) => lines.push((i + 1) + '. [' + r.score + '/10] ' + r.title + ' - ' + r.company + (r.location ? ' (' + r.location + ')' : ''), '   ' + r.reason, '   ' + r.url + ' (via ' + r.source + ')', ''));
return [{ json: { text: lines.join('\n').trim().slice(0, 4000) } }];
